// PanelLayout.swift — Phase 8 hardware panel layouts. One JSON description
// (Resources/Panels.json, generated by tools/panels.py) drives the SwiftUI
// rack and the web test build, so both show the same panels.
//
// A panel lists its controls by parameter identifier. The style of each
// control follows from the parameter (see `ControlStyle.for`), except that
// the panel's `sliders` form the main vertical slider bank. Jacks come from
// the rack catalogue at run time via `rack` (a rack module key; "" = none).
import Foundation

public struct PanelModule: Codable, Sendable, Hashable, Identifiable {
    public var key: String
    public var rack: String
    public var title: String
    public var diagram: String
    public var sliders: [String]
    public var knobs: [String]
    public var switches: [String]
    /// Width in panel units (1 hp = PanelLayout.hpWidth points).
    public var hp: Int
    /// True: the knobs and switches live in a pop-up window opened from a
    /// button on the panel; only the sliders and jacks stay on the front.
    public var popup: Bool
    public var id: String { key }

    /// Every parameter identifier on the panel, in reading order.
    public var parameters: [String] { sliders + knobs + switches }

    private enum CodingKeys: String, CodingKey { case key, rack, title, diagram, sliders, knobs, switches, hp, popup }
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        key = try c.decode(String.self, forKey: .key); rack = try c.decode(String.self, forKey: .rack)
        title = try c.decode(String.self, forKey: .title); diagram = try c.decode(String.self, forKey: .diagram)
        sliders = try c.decode([String].self, forKey: .sliders); knobs = try c.decode([String].self, forKey: .knobs)
        switches = try c.decode([String].self, forKey: .switches); hp = try c.decode(Int.self, forKey: .hp)
        popup = try c.decodeIfPresent(Bool.self, forKey: .popup) ?? false   // older Panels.json has no popup key
    }
}

public struct PanelRow: Codable, Sendable, Hashable, Identifiable {
    public var id: String
    public var name: String
    public var modules: [PanelModule]
}

public struct PanelLayout: Codable, Sendable {
    public var version: Int
    public var hpWidth: Double
    public var rows: [PanelRow]

    /// The bundled layout. Falls back to an empty rack (never crashes) if the
    /// resource is missing or malformed; `PanelLayoutTests` guard against that.
    public static let standard: PanelLayout = {
        guard let url = Bundle.module.url(forResource: "Panels", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let layout = try? JSONDecoder().decode(PanelLayout.self, from: data) else {
            return PanelLayout(version: 1, hpWidth: 22, rows: [])
        }
        return layout
    }()

    public var modules: [PanelModule] { rows.flatMap(\.modules) }
    public func module(_ key: String) -> PanelModule? { modules.first { $0.key == key } }

    /// Identifiers on panels that the registry does not know (should be empty).
    public var unknownParameters: [String] {
        modules.flatMap(\.parameters).filter { ParameterRegistry.spec(identifier: $0) == nil }
    }
}

/// How a parameter is drawn on a panel.
public enum ControlStyle: String, Sendable, CaseIterable {
    case fader       // vertical slider, white cap
    case knob        // silver cap, black pointer
    case lever       // toggle / 2–4 position lever switch
    case rotary      // rotary selector (5+ positions)

    public static func `for`(_ spec: ParameterSpec, inSliderBank: Bool) -> ControlStyle {
        if inSliderBank { return .fader }
        if spec.unit == .boolean { return .lever }
        if let s = spec.valueStrings { return s.count <= 4 ? .lever : .rotary }
        return .knob
    }
}

/// The silkscreen legend for a control: the parameter name without the words
/// the panel title already carries ("VCO 1 Pulse Width" → "pulse width").
public enum PanelLegend {
    private static let prefixes = ["VCO", "Filter", "EG", "LFO", "Seq", "Arp", "Gen", "FX", "Effects", "Mod", "Macro", "OTA",
                                   "Comb", "Formant", "VCA", "Noise", "Ring Mod", "S&H", "Slew", "Follower", "Diode Ladder",
                                   "Ladder", "VC BPF", "Mixer", "Fixed Bank", "Switch", "Gate Delay", "Voltage Processor"]
    public static func text(for spec: ParameterSpec) -> String {
        var words = spec.displayName.split(separator: " ").map(String.init)
        if let first = words.first, prefixes.contains(where: { $0.split(separator: " ").first.map(String.init) == first }) {
            words.removeFirst()
            if let n = words.first, n.count <= 2, n.allSatisfy({ $0.isNumber || $0.isUppercase }) { words.removeFirst() }
            if words.first == "Mod" { words.removeFirst() }
        }
        let t = words.joined(separator: " ").lowercased()
        return t.isEmpty ? spec.displayName.lowercased() : t
    }
}

// MARK: - Seeded wear (shared algorithm with web/app.js `wearSVG`)

/// Procedural, seeded wear marks for one module panel: hairline scratches
/// (mostly in the lower half, near jacks and slots), paint rub-through on
/// the edges, and soft smudges. Stable per module key; scaled by the Wear
/// amount at draw time.
public struct WearPattern: Sendable, Equatable {
    public struct Scratch: Sendable, Equatable { public var x, y, dx, dy, width, opacity: Double }
    public struct Rub: Sendable, Equatable { public var x, y, rx, ry: Double }
    public struct Smudge: Sendable, Equatable { public var x, y, r: Double }
    public var scratches: [Scratch] = []
    public var rubs: [Rub] = []
    public var smudges: [Smudge] = []

    /// FNV-1a over UTF-16 code units (matches the web build's `hash`).
    public static func seed(_ key: String) -> UInt32 {
        var h: UInt32 = 2166136261
        for u in key.utf16 { h = (h ^ UInt32(u)) &* 16777619 }
        return h
    }

    /// Generates the pattern for a panel of size w × h (points).
    public static func make(key: String, width w: Double, height h: Double) -> WearPattern {
        var s = seed(key); if s == 0 { s = 1 }
        func r() -> Double { s = s &* 1664525 &+ 1013904223; return Double(s) / 4294967296.0 }
        var p = WearPattern()
        for _ in 0..<26 {
            let x = r() * w, y = h * (0.45 + 0.55 * r()), len = 6 + r() * 26, ang = (r() - 0.5) * 1.2
            p.scratches.append(Scratch(x: x, y: y, dx: cos(ang) * len, dy: sin(ang) * len, width: 0.3 + r() * 0.5, opacity: 0.25 + r() * 0.45))
        }
        for _ in 0..<10 {
            let y = r() * h, side = r() < 0.5 ? 0 : w
            p.rubs.append(Rub(x: side, y: y, rx: 1 + r() * 2.5, ry: 3 + r() * 10))
        }
        for _ in 0..<4 { p.smudges.append(Smudge(x: r() * w, y: r() * h, r: 8 + r() * 14)) }
        return p
    }
}

// MARK: - Appearance (saved with the project)

/// Panel appearance (Phase 8): the rack's Wear amount, per-module overrides,
/// and whether brushed metal reacts to device tilt.
public struct AppearanceState: Codable, Sendable, Equatable {
    public static let defaultWear = 0.35
    public var wear: Double
    public var moduleWear: [String: Double]
    public var tiltHighlights: Bool

    public init(wear: Double = AppearanceState.defaultWear, moduleWear: [String: Double] = [:], tiltHighlights: Bool = true) {
        self.wear = wear; self.moduleWear = moduleWear; self.tiltHighlights = tiltHighlights
    }

    enum CodingKeys: String, CodingKey { case wear, moduleWear, tiltHighlights }
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        wear = (try? c.decodeIfPresent(Double.self, forKey: .wear)) ?? Self.defaultWear
        moduleWear = (try? c.decodeIfPresent([String: Double].self, forKey: .moduleWear)) ?? [:]
        tiltHighlights = (try? c.decodeIfPresent(Bool.self, forKey: .tiltHighlights)) ?? true
    }

    public var isDefault: Bool { self == AppearanceState() }

    /// Wear for one module: its override, else the rack's.
    public func wear(for module: String) -> Double { moduleWear[module] ?? wear }

    public func sanitized() -> AppearanceState {
        func unit(_ v: Double) -> Double? { v.isFinite ? min(max(v, 0), 1) : nil }
        var out = AppearanceState(wear: unit(wear) ?? Self.defaultWear, moduleWear: [:], tiltHighlights: tiltHighlights)
        for (k, v) in moduleWear.prefix(256) where !k.isEmpty && k.count <= 64 { if let u = unit(v) { out.moduleWear[k] = u } }
        return out
    }
}
